<?php
require_once 'functions.php';require_login();$id=uid();$s=$pdo->prepare("SELECT DATE_FORMAT(transaction_date,'%Y-%m') m,SUM(CASE WHEN type='income' THEN amount ELSE 0 END) income,SUM(CASE WHEN type='expense' THEN amount ELSE 0 END) expenses FROM transactions WHERE user_id=? AND transaction_date>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY DATE_FORMAT(transaction_date,'%Y-%m') ORDER BY m");$s->execute([$id]);$map=[];foreach($s->fetchAll() as $r)$map[$r['m']]=$r;$labels=$in=$ex=[];for($i=11;$i>=0;$i--){$k=date('Y-m',strtotime(date('Y-m-01')." -$i months"));$labels[]=date('M Y',strtotime($k.'-01'));$in[]=(float)($map[$k]['income']??0);$ex[]=(float)($map[$k]['expenses']??0);}$s=$pdo->prepare("SELECT category,SUM(amount) total FROM transactions WHERE user_id=? AND type='expense' GROUP BY category ORDER BY total DESC");$s->execute([$id]);$cat=$s->fetchAll();$cl=array_column($cat,'category');$cv=array_map('floatval',array_column($cat,'total'));start_page('Reports','reports.php');?>
<div class="page-intro"><div><h1>Your money, in perspective.</h1><p>Visualize patterns and plan ahead.</p></div><span class="date-chip">▥ Analytics</span></div><div class="charts"><section class="panel"><div class="panel-head"><div><h2>Income vs expenses</h2><p>Monthly comparison · last 12 months</p></div><span class="round-icon">⌁</span></div><canvas id="lineChart" height="260"></canvas></section><section class="panel"><div class="panel-head"><div><h2>Spending by category</h2><p>Where your expenses go</p></div><span class="round-icon">◉</span></div><?php if(!$cv):?><div class="empty">Add expense transactions to see your breakdown.</div><?php endif;?><canvas id="doughnutChart" height="260"></canvas></section></div><script>
const labels=<?=json_encode($labels)?>, income=<?=json_encode($in)?>, expenses=<?=json_encode($ex)?>, cats=<?=json_encode($cl)?>, values=<?=json_encode($cv)?>;
new Chart(document.getElementById('lineChart'),{type:'line',data:{labels,datasets:[{label:'Income',data:income,borderColor:'#16a085',backgroundColor:'rgba(22,160,133,.12)',fill:true,tension:.35},{label:'Expenses',data:expenses,borderColor:'#f08a5d',backgroundColor:'rgba(240,138,93,.08)',fill:true,tension:.35}]},options:{responsive:true,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true}}}});
new Chart(document.getElementById('doughnutChart'),{type:'doughnut',data:{labels:cats,datasets:[{data:values,backgroundColor:['#7568e8','#37b9a1','#f5a66a','#ef7897','#68a5ee','#b3a2ed','#f2ce68','#7ec9d1','#e99b77'],borderWidth:3}]},options:{responsive:true,cutout:'65%',plugins:{legend:{position:'bottom'}}}});
</script><?php end_page();?>
